import { escapeHTML } from "./dom";

/**
 * Resolves the optimised WebP variants generated by `npm run images`.
 * Every file under src/assets/images is bundled by Vite with a hashed URL,
 * so the site never hotlinks the Rockstar CDN.
 */

const files = import.meta.glob<string>("../assets/images/**/*.webp", {
  eager: true,
  query: "?url",
  import: "default",
});

type VariantMap = Map<number, string>;

const registry = new Map<string, VariantMap>();

for (const [path, url] of Object.entries(files)) {
  const relative = path.replace("../assets/images/", "");
  const match = /^(.*)-(\d+)\.webp$/.exec(relative);
  if (!match) continue;
  const [, key, widthText] = match;
  if (key === undefined || widthText === undefined) continue;
  const width = Number(widthText);
  let variants = registry.get(key);
  if (!variants) {
    variants = new Map();
    registry.set(key, variants);
  }
  variants.set(width, url);
}

function variantsOf(key: string): VariantMap | undefined {
  return registry.get(key);
}

export function imageURL(key: string, width = 1280): string {
  const variants = variantsOf(key);
  if (!variants || variants.size === 0) return "";
  const exact = variants.get(width);
  if (exact) return exact;
  const widths = Array.from(variants.keys()).sort((a, b) => a - b);
  const larger = widths.find((candidate) => candidate >= width);
  const chosen = larger ?? widths[widths.length - 1];
  return chosen === undefined ? "" : variants.get(chosen) ?? "";
}

export function imageSrcset(key: string, widths: number[] = [640, 1280]): string {
  const variants = variantsOf(key);
  if (!variants) return "";
  return widths
    .filter((width) => variants.has(width))
    .map((width) => `${variants.get(width)} ${width}w`)
    .join(", ");
}

export interface ImageOptions {
  widths?: number[];
  sizes?: string;
  className?: string;
  loading?: "lazy" | "eager";
  decoding?: "async" | "sync";
  width?: number;
  height?: number;
}

export function imageTag(key: string, alt: string, options: ImageOptions = {}): string {
  const widths = options.widths ?? [640, 1280];
  const src = imageURL(key, widths[widths.length - 1] ?? 1280);
  if (!src) return "";
  const srcset = imageSrcset(key, widths);
  const sizes = options.sizes ? ` sizes="${options.sizes}"` : "";
  const className = options.className ? ` class="${options.className}"` : "";
  const loading = options.loading ?? "lazy";
  const decoding = options.decoding ?? "async";
  const width = options.width ? ` width="${options.width}"` : "";
  const height = options.height ? ` height="${options.height}"` : "";
  return `<img src="${src}"${srcset ? ` srcset="${srcset}"` : ""}${sizes}${className} alt="${escapeHTML(alt)}" loading="${loading}" decoding="${decoding}"${width}${height}>`;
}
